SELECT td.chembl_id AS target_chembl_id, td.pref_name AS target_name, td.target_type, cs.accession AS protein_accession, cs.sequence AS protein_sequence FROM target_dictionary td JOIN target_components tc ON td.tid = tc.tid JOIN component_sequences cs ON tc.component_id = cs.component_id WHERE td.target_type = 'SINGLE PROTEIN' ORDER BY td.chembl_id, td.pref_name, td.target_type, cs.accession, cs.sequence
